#include <bits/stdc++.h>
using namespace std;

bool eh_primo(int x) {
    if (x < 2) return false;
    if (x % 2 == 0) return x == 2;

    for (int i = 3; 1LL * i * i <= x; i += 2) {
        if (x % i == 0) return false;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    if (n % 2 != 0) {
        if (eh_primo(n - 2)) {
            cout << 2 << ' ' << n - 2 << '\n';
        }
        return 0;
    }

    for (int a = n / 2 - 1; a >= 2; --a) {
        int b = n - a;
        if (eh_primo(a) && eh_primo(b)) {
            cout << a << ' ' << b << '\n';
            break;
        }
    }

    return 0;
}

